create table "programs"."program_assessment_responses" (
    "id" bigint generated by default as identity not null,
    "user_id" text not null default ''::text,
    "assessment" text not null,
    "responses" jsonb not null,
    "timestamp" timestamp with time zone not null default now()
);


alter table "programs"."program_assessment_responses" enable row level security;

create table "programs"."program_assessments" (
    "id" text not null,
    "desc" text not null,
    "program" text not null,
    "created_at" timestamp with time zone not null default now(),
    "question_ids" jsonb not null
);


alter table "programs"."program_assessments" enable row level security;

create table "programs"."program_feedback" (
    "id" bigint generated by default as identity not null,
    "title" text not null,
    "body" text not null,
    "program" text not null,
    "question_id" text,
    "question_response" text,
    "order" bigint,
    "links" jsonb
);


alter table "programs"."program_feedback" enable row level security;

create table "programs"."program_message_claire_prompts" (
    "id" bigint generated by default as identity not null,
    "message_id" bigint not null,
    "prompt_id" bigint not null
);


alter table "programs"."program_message_claire_prompts" enable row level security;

